self.addEventListener('activate', (event) => {
  const keep = new Set(['workbox-precache-v2', 'static-v1', 'img-v1', 'pages-v1', 'api-v1', 'feeds-v1']);
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.map((n) => { if (!Array.from(keep).some(k => n.includes(k))) { return caches.delete(n); } }));
  })());
});
